  ('74893', 'Desodorante body spray de mujer dolce de Egeo 100ML', 'Higiene y cuidado personal', 'Desodorantes', 'Compra el body spray Dolce para mujer. Protección duradera y fragancia sofisticada en un solo paso. ¡Frescura y estilo al instante!', '["Marca: EGEO","Tipo: Desodorantes","Presentación: 100ML","Disponibilidad: Disponible","Canal: tienda oficial O Boticário Colombia"]'::jsonb, 44900, 'COP', '100ML', true, 'https://www.oboticario.com.co/products/egeo-desodorante-body-spray-dolce-woman-100ml?variant=Default+Title', 'https://www.oboticario.com.co/collections/all', 'Agosto', 2026, '2026-08-12'::date, 'activo', 'https://www.oboticario.com.co/products/egeo-desodorante-body-spray-dolce-woman-100ml'),
