  ('73745', 'Men Pomada Modeladora De Alta Fijacion 100G', 'Otros', 'No especificada', 'Define tu estilo con la Pomada Modeladora de Alta Fijación de Boticário Men para hombres. Crea peinados impecables que perduran todo el día. La clave para un look impecable y duradero. ¡Potencia tu estilo con nuestra fórmula de alta fijación. Contamos con envíos a todo el país. Ingresa aquí y lleva tu pomada.', '["Marca: BOTICARIO MEN","Tipo: No especificada","Presentación: 100G","Disponibilidad: Agotado","Canal: tienda oficial O Boticário Colombia"]'::jsonb, 39900, 'COP', '100G', false, 'https://www.oboticario.com.co/products/men-pomada-modeladora-de-alta-fijacion-100g', 'https://www.oboticario.com.co/collections/all', 'Agosto', 2026, '2026-08-12'::date, 'retirado', 'https://www.oboticario.com.co/products/men-pomada-modeladora-de-alta-fijacion-100g'),
  ('62330', 'Perfume para mujer Floratta Red EDT 75Ml', 'Perfumería', 'Femenina', 'Compra Floratta Red, el perfume femenino con aroma floral frutal irresistible. Elegancia y frescura en cada nota. Ingresa aquí y llévalo. Envíos a todo el país.', '["Marca: FLORATTA","Tipo: Femenina","Presentación: 75Ml","Disponibilidad: Agotado","Canal: tienda oficial O Boticário Colombia"]'::jsonb, 159900, 'COP', '75Ml', false, 'https://www.oboticario.com.co/products/floratta-edt-red-75ml', 'https://www.oboticario.com.co/collections/all', 'Agosto', 2026, '2026-08-12'::date, 'retirado', 'https://www.oboticario.com.co/products/floratta-edt-red-75ml'),
